cat > /tmp/lz4exp/argparse/pty2.py <<'EOF'
import os, pty, sys, select, tty, termios
# usage: pty2.py <in:tty|pipe|file:PATH|null> <out:tty|pipe> -- cmd args...
mode_in, mode_out = sys.argv[1], sys.argv[2]
assert sys.argv[3]=='--'
argv = sys.argv[4:]
mfd_in = mfd_out = None
sfd_in = sfd_out = None
if mode_in=='tty':
    mfd_in, sfd_in = pty.openpty()
if mode_out=='tty':
    mfd_out, sfd_out = pty.openpty()
r_pipe=w_pipe=None
if mode_in=='pipe':
    r_pipe, w_pipe = os.pipe()
out_r=out_w=None
if mode_out=='pipe':
    out_r, out_w = os.pipe()
err_r, err_w = os.pipe()
pid = os.fork()
if pid==0:
    if mode_in=='tty': os.dup2(sfd_in,0)
    elif mode_in=='pipe': os.dup2(r_pipe,0)
    elif mode_in.startswith('file:'):
        f=os.open(mode_in[5:], os.O_RDONLY); os.dup2(f,0)
    else:
        f=os.open('/dev/null', os.O_RDONLY); os.dup2(f,0)
    if mode_out=='tty': os.dup2(sfd_out,1)
    else: os.dup2(out_w,1)
    os.dup2(err_w,2)
    for fd in set(x for x in [mfd_in,sfd_in,mfd_out,sfd_out,r_pipe,w_pipe,out_r,out_w,err_r,err_w] if x is not None):
        try:
            if fd>2: os.close(fd)
        except: pass
    os.execv(argv[0], argv)
# parent
for fd in [sfd_in, sfd_out, r_pipe, out_w, err_w]:
    if fd is not None:
        try: os.close(fd)
        except: pass
if w_pipe is not None: os.close(w_pipe)
readers=[]
if mfd_out is not None: readers.append(mfd_out)
if out_r is not None: readers.append(out_r)
readers.append(err_r)
bufs={fd:b'' for fd in readers}
while readers:
    r,_,_=select.select(readers,[],[],5)
    if not r: break
    for fd in r:
        try: d=os.read(fd,65536)
        except OSError: d=b''
        if not d: readers.remove(fd)
        else: bufs[fd]+=d
_,status=os.waitpid(pid,0)
so = bufs.get(mfd_out if mfd_out is not None else out_r, b'')
se = bufs.get(err_r, b'')
print("EXIT=%d" % (status>>8 if (status & 0xff)==0 else -(status&0x7f)))
print("STDOUT=%r" % so)
print("STDERR=%r" % se)
EOF
